#!/usr/bin/env python3
"""Regenerate the auto-generated documentation pages from the data and
results so that docs never drift from the model:

docs/generated/assumption_tables.md   every input table + bibliography
docs/generated/scenario_matrix.md     scenario catalogue with lineage
docs/generated/results_tables.md      headline indicators per scenario
docs/generated/technology_list.md     every technology / commodity / UDC
"""
from __future__ import annotations

import sys
from pathlib import Path

import pandas as pd

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))
from kezer.build import build_base  # noqa: E402
from kezer.scenarios import SCENARIOS, lineage  # noqa: E402

A = ROOT / "data" / "assumptions"
OUT = ROOT / "docs" / "generated"
RES = ROOT / "results" / "scenarios"


def md(df: pd.DataFrame) -> str:
    df = df.fillna("")
    cols = [str(c) for c in df.columns]
    lines = ["| " + " | ".join(cols) + " |", "|" + "---|" * len(cols)]
    for r in df.itertuples(index=False):
        lines.append("| " + " | ".join(str(v).replace("|", "/").replace("\n", " ") for v in r) + " |")
    return "\n".join(lines) + "\n"


def assumptions():
    s = ["# Input assumption tables\n",
         "_Auto-generated by `scripts/make_docs.py` from `data/assumptions/*.csv`. Edit the CSVs, not this page._\n",
         "Confidence: **A** official statistic used directly; **B** official/peer-reviewed source with modeller "
         "transformation; **C** modeller assumption informed by the cited literature (tested in sensitivities).\n"]
    titles = {
        "vehicle_technologies.csv": "Road vehicle technologies (2024 stock, activity, energy, costs)",
        "rail_technologies.csv": "Rail technologies", "charging_technologies.csv": "EV charging and V2G",
        "fuels.csv": "Transport fuel supply", "hydrogen.csv": "Hydrogen supply",
        "demand_growth.csv": "Transport demand growth rates (per year)",
        "zev_sales_cap_reference.csv": "Reference diffusion limits: maximum zero-emission share of new vehicles",
        "hev_sales_cap.csv": "Maximum hybrid share of new cars",
        "charging_profiles.csv": "Charging profiles (share of daily charging energy by time bracket)",
        "power_cost_learning.csv": "Cost-learning multipliers applied to CCG PSM v3 power costs",
        "constants.csv": "Scalars and conversion factors",
    }
    for f, t in titles.items():
        s.append(f"\n## {t}\n\n`data/assumptions/{f}`\n\n")
        s.append(md(pd.read_csv(A / f)))
    s.append("\n## Bibliography (source_id)\n\n")
    s.append(md(pd.read_csv(A / "sources.csv")))
    (OUT / "assumption_tables.md").write_text("".join(s))


def scenarios():
    rows = []
    for sid, sc in SCENARIOS.items():
        rows.append({"ID": sid, "Name": sc.name, "Family": sc.family, "Builds on": sc.parent or "-",
                     "MUIO case run layers": " -> ".join("SC_0" if x == "S0_REF" else x for x in lineage(sid)),
                     "Definition": sc.description})
    s = ["# Scenario matrix\n", "_Auto-generated from `src/kezer/scenarios.py`._\n\n", md(pd.DataFrame(rows))]
    (OUT / "scenario_matrix.md").write_text("".join(s))


def techlist():
    m = build_base()
    t = pd.DataFrame([{"Technology": k, "Group": v.group, "Class": v.vclass, "Drivetrain": v.drivetrain,
                       "ZEV": "yes" if v.zev else "", "Capacity unit": v.cap_unit, "Activity unit": v.act_unit,
                       "Description": v.description} for k, v in sorted(m.techs.items())])
    c = pd.DataFrame([{"Commodity": k, "Balance level": {"Ts": "timeslice", "Se": "seasonal (intra-day)",
                                                          "An": "annual"}[v.balance],
                       "Unit": v.unit, "Description": v.description} for k, v in sorted(m.comms.items())])
    u = pd.DataFrame([{"UDC": k, "Type": "<=" if v.tag == 0 else "=", "Description": v.description}
                      for k, v in sorted(m.udcs.items())])
    cal = m.info["calibration"]
    s = ["# Model sets\n", "_Auto-generated from the model builder._\n",
         f"\n{len(t)} technologies, {len(c)} commodities, {len(u)} user-defined constraints, "
         f"{len(m.sets['TIMESLICE'])} timeslices, years {m.sets['YEAR'][0]}-{m.sets['YEAR'][-1]}.\n",
         "\n## Technologies\n\n", md(t), "\n## Commodities\n\n", md(c), "\n## User-defined constraints\n\n", md(u),
         "\n## 2024 calibration\n\n",
         md(pd.DataFrame([{k: round(float(v), 4) for k, v in cal.items()}])),
         "\n## Power capacity carried into 2024 as residual (GW, from PSM v3 committed builds 2019-2023)\n\n",
         md(pd.DataFrame([{"Technology": k, "GW": round(float(v), 4)}
                          for k, v in m.info["power_pre2024_capacity_added_as_residual_GW"].items()])),
         "\n## PSM v3 MaxCapacity values lifted to hold committed builds (tech, year: PSM value -> used)\n\n",
         md(pd.DataFrame([{"Technology": k[1], "Year": k[2], "PSM": round(a, 4), "Used": round(b, 4)}
                          for k, (a, b) in m.info["psm_maxcap_lifted"].items()])),
         "\n## Transport service demand in 2024 (from calibrated stock x km x occupancy)\n\n",
         md(pd.DataFrame([{"Commodity": k, "2024 (Gpkm or Gtkm)": round(v, 2)}
                          for k, v in m.info["transport_demand_2024"].items()]))]
    (OUT / "technology_list.md").write_text("".join(s))


def results():
    if not RES.exists():
        return
    rows = []
    for d in sorted(RES.iterdir()):
        try:
            sm = pd.read_csv(d / "summary.csv").iloc[0]
            em = pd.read_csv(d / "emissions.csv")
            ad = pd.read_csv(d / "adequacy.csv").set_index("YEAR")
            ed = pd.read_csv(d / "electricity_demand.csv").set_index("YEAR")
            fl = pd.read_csv(d / "fleet.csv")
            fu = pd.read_csv(d / "fuels.csv")
        except FileNotFoundError:
            continue
        road = em[em.sector == "Road transport"].groupby("YEAR").MtCO2.sum()
        f50 = fl[fl.YEAR == 2050]
        rows.append({
            "Scenario": d.name,
            "Total cost 2024-60 (bn US$, disc.)": round(sm.total_discounted_system_cost_MUSD / 1000, 1),
            "Road CO2 2030 (Mt)": round(road.get(2030, 0), 2), "Road CO2 2050 (Mt)": round(road.get(2050, 0), 2),
            "Cum. road CO2 2024-50 (Mt)": round(road[road.index <= 2050].sum(), 0),
            "ZEV share of vehicles in use 2050 (%)": round(100 * f50[f50.zev].in_use.sum() / max(f50.in_use.sum(), 1), 1),
            "Idle (stranded) fossil vehicles 2050 (k)": round((f50[~f50.zev].value.sum() - f50[~f50.zev].in_use.sum()) / 1000, 0),
            "EV charging 2050 (TWh)": round(ed.loc[2050, "ev_charging_TWh"], 1),
            "H2 electricity 2050 (TWh)": round(ed.loc[2050, "hydrogen_TWh"], 1),
            "Peak 2050 (GW)": round(ad.loc[2050, "peak_GW"], 2),
            "EV at peak 2050 (GW)": round(ad.loc[2050, "ev_at_peak_GW"], 2),
            "Reserve margin 2050": round(ad.loc[2050, "reserve_margin"], 2),
            "Max firm shortfall (GW)": round(ad.reserve_shortfall_GW.max(), 2),
            "Unserved energy 2024-50 (TWh)": round(ad.loc[:2050, "unserved_energy_TWh"].sum(), 2),
            "Fuel imports 2024-50 (bn US$, undisc.)": round(fu[fu.YEAR <= 2050].import_bill_MUSD.sum() / 1000, 0),
        })
    if rows:
        s = ["# Headline results\n", "_Auto-generated from `results/scenarios/`._\n\n", md(pd.DataFrame(rows))]
        (OUT / "results_tables.md").write_text("".join(s))
        pd.DataFrame(rows).to_csv(ROOT / "results" / "headline_indicators.csv", index=False)


if __name__ == "__main__":
    OUT.mkdir(parents=True, exist_ok=True)
    assumptions()
    scenarios()
    techlist()
    results()
    print("docs written to", OUT)
